#include <bits/stdc++.h>
using namespace std;
int main(){
    int T;
    scanf("%d",&T);
    while(T--){
        int n;
        scanf("%d",&n);
        vector<int> p(n+1);
        for(int i=1;i<=n;i++) scanf("%d",&p[i]);
        vector<pair<int,int>> edges(n-1);
        vector<vector<pair<int,int>>> adj(n+1);
        for(int i=0;i<n-1;i++){
            int u,v; scanf("%d%d",&u,&v);
            edges[i]={u,v};
            adj[u].push_back({v,i});
            adj[v].push_back({u,i});
        }
        // BFS to find parent and subtree info
        vector<int> par(n+1,-1), depth(n+1,0), order;
        vector<int> parent_edge(n+1,-1);
        vector<bool> vis(n+1,false);
        queue<int> bfs;
        bfs.push(1); vis[1]=true;
        while(!bfs.empty()){
            int u=bfs.front(); bfs.pop(); order.push_back(u);
            for(auto [v,ei]:adj[u]) if(!vis[v]){
                vis[v]=true; par[v]=u; depth[v]=depth[u]+1; parent_edge[v]=ei; bfs.push(v);
            }
        }
        vector<vector<int>> results;
        for(int iter=0;iter<2*n;iter++){
            bool done=true;
            for(int i=1;i<=n;i++) if(p[i]!=i){done=false;break;}
            if(done) break;
            // For each edge, check if swapping helps: p[u] should be in subtree of v and p[v] in subtree of u (or outside)
            // Simple: swap if it reduces total displacement
            // Build matching greedily bottom-up
            vector<bool> used(n+1,false);
            vector<int> matching;
            // Process nodes bottom-up (reverse BFS order)
            for(int i=(int)order.size()-1;i>=0;i--){
                int v=order[i];
                if(par[v]==-1) continue;
                int u=par[v];
                int ei=parent_edge[v];
                if(used[u]||used[v]) continue;
                // Swap if beneficial: p[u]!=u or p[v]!=v, and swapping moves at least one closer
                if(p[u]==u && p[v]==v) continue;
                // Check: after swap, is it not worse?
                // Heuristic: swap if p[v] is "above" v or p[u] is "below" u
                if(p[u]!=u || p[v]!=v){
                    swap(p[u],p[v]);
                    matching.push_back(ei);
                    used[u]=used[v]=true;
                }
            }
            if(matching.empty()) break; // shouldn't happen if not done
            results.push_back(matching);
        }
        printf("%d\n",(int)results.size());
        for(auto&m:results){
            printf("%d",(int)m.size());
            for(int ei:m) printf(" %d",ei+1);
            printf("\n");
        }
    }
}
